function Lesson({ number, title, lead, children }: { number: string; title: string; lead: ReactNode; children: ReactNode }) {
  return <article className="regression-modeling regression-diagnostics" aria-labelledby={`rd-${number}`}><header><p className="rm-eyebrow">Chapter 14 · Lesson {number}</p><h1 id={`rd-${number}`}>{title}</h1><p>{lead}</p></header>{children}</article>
}
function Term({ children, definition }: { children: ReactNode; definition: string }) {
  const id = useId()
  const [open, setOpen] = useState(false)
  return <span className="rd-term"><button type="button" aria-describedby={open ? id : undefined} onMouseEnter={() => setOpen(true)} onMouseLeave={event => { if (document.activeElement !== event.currentTarget) setOpen(false) }} onFocus={() => setOpen(true)} onBlur={() => setOpen(false)} onClick={event => { event.currentTarget.focus(); setOpen(true) }} onKeyDown={event => { if (event.key === 'Escape') setOpen(false) }}>{children}</button>{open && <span id={id} role="tooltip" className="rd-term-definition">{definition}</span>}</span>
}
const residualDefinition = 'Residuals are prediction errors: actual value − predicted value. If a delivery takes 20 minutes and the model predicts 18, its residual is +2 minutes.'
const coefficientTerms: Record<string, string> = {
  Coefficient: 'A number the model uses to multiply an input. Here, the accommodates coefficient says how much predicted price changes for one extra guest, keeping other inputs fixed.',
  Estimate: 'The coefficient value calculated from this dataset. It is an estimate, so another sample could give a different value.',
  'Standard error': 'How uncertain the coefficient estimate is. A smaller standard error means a more precise estimate. This is not the size of the model’s prediction errors.',
  't-value': 'The estimate divided by its standard error. It shows how far the estimate is from zero compared with its uncertainty.',
  'p-value': 'If the true coefficient were zero, how likely would a t-value this far from zero or farther be? A small p-value gives evidence of a relationship.',
}
function CoefficientTerm({ name, children }: { name: string; children?: ReactNode }) { return <Term definition={coefficientTerms[name]}>{children ?? name}</Term> }
const recapAreas = [
  { label: 'Regression formula: Y and Xs', x: 17.3, y: 12, w: 70, h: 8.4, help: 'Price is the dependent variable Y: what we want to predict. Accommodates (guest capacity), bedrooms, Entire.place, host_has_profile_pic, Hotel.room and Private.room are the independent variables Xs: inputs used to predict price. data = d.2 names the dataset.' },
  { label: 'Residuals / errors', x: 17.3, y: 22.8, w: 47.5, h: 11.8, help: 'Residual = actual price − predicted price. Min −135.057: the model predicted $135.057 too high. 1Q −27.091 is the first quartile (25% point); median −8.091 is the middle (50%); 3Q 20.909 is the third quartile (75% point). Max +194.388: the model predicted $194.388 too low. This is the largest absolute error shown on these fitted records, not a limit on future errors.' },
  { label: 'Y-intercept', x: 17.5, y: 43.5, w: 31.3, h: 3.7, help: 'The intercept, 47.9501, is the starting predicted price when all inputs are zero. That combination may not describe a realistic listing.' },
  { label: 'IV coefficients', x: 17.5, y: 47.2, w: 31.3, h: 20.6, help: 'Each independent variable (input) has a coefficient: its multiplier in the prediction. Accommodates has coefficient 5.7166, so one extra guest adds about $5.72 to predicted price, keeping other inputs fixed. For a yes/no input, it compares yes with no.' },
  { label: 'Estimate', x: 39.5, y: 39.8, w: 9.3, h: 3.7, help: coefficientTerms.Estimate },
  { label: 'Coefficient standard errors', x: 49, y: 39.8, w: 11.5, h: 28, help: coefficientTerms['Standard error'] },
  { label: 't-values', x: 60.5, y: 39.8, w: 8, h: 28, help: coefficientTerms['t-value'] },
  { label: 'Coefficient p-values', x: 68.5, y: 39.8, w: 13.8, h: 28, help: coefficientTerms['p-value'] + ' Below 0.05 is the usual cutoff for finding evidence of a relationship.' },
  { label: 'Significance stars', x: 17.5, y: 69.8, w: 65, h: 5, help: 'The stars summarize the coefficient p-values. More stars mean smaller p-values, not a larger effect or more accurate predictions. The line gives the cutoffs.' },
  { label: 'Residual standard error', x: 17.5, y: 77.8, w: 65, h: 3.5, help: '40.31 summarizes the spread of prediction errors in price units on the fitted data. The 29,790 degrees of freedom remain after estimating the model’s seven coefficients. This differs from uncertainty in an individual coefficient.' },
  { label: 'R-squared', x: 17.5, y: 81.3, w: 31.5, h: 3.8, help: 'R² = 0.4164: the model explains about 41.64% of the variation in listing prices around their mean on these records. This does not mean predictions are 41.64% accurate.' },
  { label: 'Adjusted R-squared', x: 49, y: 81.3, w: 31, h: 3.8, help: 'Adjusted R² = 0.4163: R² with a penalty for the number of inputs. Adding an input must help enough to offset that penalty.' },
  { label: 'F-statistic', x: 17.5, y: 85.2, w: 20.5, h: 3.7, help: '3543 is the whole-model F-test score. It compares explained variation per tested input with unexplained variation per remaining degree of freedom. A larger score gives stronger evidence against all input coefficients being zero.' },
  { label: 'F-test degrees of freedom', x: 38, y: 85.2, w: 20.5, h: 3.7, help: '6 is the number of input coefficients tested together. 29,790 is the remaining degrees of freedom: 29,797 records minus six input coefficients minus one intercept.' },
  { label: 'F-significance / whole-model p-value', x: 58.5, y: 85.2, w: 20.2, h: 3.7, help: 'F-significance is the p-value for the whole model. If all input coefficients were truly zero, how likely would an F-score this large or larger be? Here it is below 0.00000000000000022: strong evidence that at least one input is related to price.' },
]
function RecapGraphic() {
  const id = useId()
  const [tip, setTip] = useState<{ index: number; left: number; top: number } | null>(null)
  const show = (index: number, element: HTMLElement) => {
    const box = element.getBoundingClientRect()
    setTip({ index, left: Math.max(12, Math.min(box.left, window.innerWidth - 352)), top: Math.max(12, Math.min(box.bottom + 8, window.innerHeight - 220)) })
  }
  return <><p className="rd-note">Hover over, click, or focus a highlighted part of the output for a simple explanation.</p><figure className="rd-source rd-recap-interactive"><img src={page243} alt="Annotated Airbnb regression output. Each outlined part has an interactive explanation."/>{recapAreas.map((area, index) => <button key={area.label} type="button" className="rd-recap-hotspot" style={{ left: `${area.x}%`, top: `${area.y}%`, width: `${area.w}%`, height: `${area.h}%` }} aria-label={area.label} aria-describedby={tip?.index === index ? id : undefined} onMouseEnter={event => show(index, event.currentTarget)} onMouseLeave={event => { if (document.activeElement !== event.currentTarget) setTip(null) }} onFocus={event => show(index, event.currentTarget)} onBlur={() => setTip(null)} onClick={event => { event.currentTarget.focus(); show(index, event.currentTarget) }} onKeyDown={event => { if (event.key === 'Escape') setTip(null) }}/>)}</figure>{tip && createPortal(<div id={id} role="tooltip" className="rd-recap-tooltip" style={{ left: tip.left, top: tip.top }}><strong>{recapAreas[tip.index].label}</strong><span>{recapAreas[tip.index].help}</span></div>, document.body)}</>
}
function Visual({ src, alt }: { src: string; alt: string }) { return <figure className="rd-source"><img src={src} alt={alt}/></figure> }
function Use({ why, when }: { why: string; when: string }) { return <aside className="rd-use"><h2>Why and when to use it</h2><p><strong>Why:</strong> {why}</p><p><strong>When:</strong> {when}</p></aside> }
function Explanation({ children }: { children: ReactNode }) { return <section className="rd-added" aria-label="Additional explanation"><h2 className="rd-added-title">A simple reference</h2>{children}</section> }
function Reference({ items }: { items: { value: string; meaning: string }[] }) { return <div className="rd-reference-cards">{items.map(item => <div key={item.value}><strong>{item.value}</strong><span>{item.meaning}</span></div>)}</div> }
function Panel({ title, children }: { title: string; children: ReactNode }) { return <section className="rm-panel"><h2>{title}</h2>{children}</section> }

export function RDIntro() { return <Lesson number="14.1" title="Intro to model diagnostics" lead="Use diagnostic metrics to evaluate regression models and understand their predictions."><Panel title="Topics we’ll cover"><div className="rd-topics">{['Sample model output','R-squared','Mean error metrics','Homoskedasticity','F-significance','T-statistics and p-values','Multicollinearity','Variance inflation factor'].map(topic => <span key={topic}>{topic}</span>)}</div></Panel><Panel title="Goals for this section"><ul><li>Interpret regression model outputs.</li><li>Calculate R², MSE, MAE and MAPE.</li><li>Compare consistent and changing residual spread.</li><li>Read model and coefficient significance, and identify overlapping predictors with VIF.</li></ul></Panel><Explanation><Panel title="One practical question: can we predict delivery time?"><div className="rd-example-flow"><div><span>Input</span><strong>Distance in km</strong></div><b aria-hidden="true">→</b><div><span>Our model’s prediction</span><strong>Delivery time in minutes</strong></div><b aria-hidden="true">→</b><div><span>Compare with reality</span><strong>Actual delivery time</strong></div></div><p>Ask three questions: are the misses small enough, are they similar across short and long trips, and are the input effects stable enough to interpret?</p></Panel><Use why="Evaluate a regression model and check whether its predictions are stable and accurate." when="After building the model, before using its predictions."/></Explanation></Lesson> }

export function RDSampleOutput() { return <Lesson number="14.2" title="Sample model output" lead="The same regression diagnostics appear in R, Excel and Python output."><Visual src={page228} alt="Course examples of R regression output, Excel summary output and Python OLS regression results."/><Explanation><OutputExample/><Use why="Understand the regression equation, errors and model coefficients." when="When reading output from R, Excel or Python."/></Explanation></Lesson> }


function Fraction({ top, bottom }: { top: ReactNode; bottom: ReactNode }) { return <span className="rd-fraction"><span>{top}</span><span>{bottom}</span></span> }
function Formula({ children, label, caption }: { children: ReactNode; label: string; caption: ReactNode }) { return <div className="rd-formula-example"><div className="rd-formula" role="math" aria-label={label}>{children}</div><p className="rd-formula-caption">{caption}</p></div> }
function ExampleTable({ caption, headers, rows }: { caption: string; headers: string[]; rows: string[][] }) {
  return <div className="rd-delivery-table"><table><caption>{caption}</caption><thead><tr>{headers.map(header => <th scope="col" key={header}>{coefficientTerms[header] ? <CoefficientTerm name={header}/> : header === "t = estimate / SE" ? <CoefficientTerm name="t-value">{header}</CoefficientTerm> : header}</th>)}</tr></thead><tbody>{rows.map((row, i) => <tr key={i}>{row.map((cell, j) => j === 0 ? <th scope="row" key={j}>{cell}</th> : <td className={cell.includes("×") || cell.startsWith("1 / (") ? "rd-inline-equation" : undefined} key={j}>{cell}</td>)}</tr>)}</tbody></table></div>
}
function OutputExample() { return <Panel title="Read one row: accommodates"><p>The Airbnb model predicts a listing’s <strong>price</strong>. “Accommodates” is the number of guests it can host.</p><div className="rd-example-flow"><div><span>Input changes</span><strong>2 guests → 3 guests</strong></div><b aria-hidden="true">→</b><div><span>Model coefficient</span><strong>+$5.7166 per guest</strong></div><b aria-hidden="true">→</b><div><span>Our model’s prediction</span><strong>About $5.72 higher</strong></div></div><p>Keep all other inputs fixed. This is a change in the model’s predicted price, not proof that adding a guest causes the actual price to rise.</p><p className="rd-note">The coefficient comes from the course output; the two guest counts illustrate how to read it.</p></Panel> }
function ErrorExample() {
  const deliveries = [{ trip: 'A', actual: 8, prediction: 10 }, { trip: 'B', actual: 10, prediction: 12 }, { trip: 'C', actual: 20, prediction: 16 }]
  return <Panel title="Three deliveries: trace every miss"><p>Illustrative times in minutes. Our model predicts delivery time; the actual time is what was observed.</p><ExampleTable caption="From observed times to error contributions" headers={['Delivery', 'Actual time', 'Our model’s prediction', 'Absolute miss', 'Squared miss', 'Percentage miss']} rows={deliveries.map(d => [d.trip, `${d.actual} min`, `${d.prediction} min`, `${Math.abs(d.actual - d.prediction)} min`, `${(d.actual - d.prediction) ** 2} min²`, `${100 * Math.abs(d.actual - d.prediction) / d.actual}%`])}/><div className="rd-error-bars"><h3>Which delivery contributes most?</h3><p>Bars show each delivery’s share of the total error for that metric.</p>{[{ name: 'Absolute error: 2 + 2 + 4 = 8', values: [2, 2, 4] }, { name: 'Squared error: 4 + 4 + 16 = 24', values: [4, 4, 16] }].map(metric => <div key={metric.name}><strong>{metric.name}</strong><div className="rd-contribution-bar">{metric.values.map((value, i) => <span key={i} className={`rd-trip-${i}`} style={{ width: `${100 * value / metric.values.reduce((a, b) => a + b, 0)}%` }}>{deliveries[i].trip}: {value}</span>)}</div></div>)}</div><Reference items={[{ value: 'MSE = 24 / 3 = 8 min²', meaning: 'C has twice the absolute miss of A, but four times its squared error. MSE gives large misses more weight.' }, { value: 'MAE = 8 / 3 ≈ 2.67 min', meaning: 'Our model misses by about 2.67 minutes on average, ignoring whether it is early or late.' }, { value: 'MAPE = 65% / 3 ≈ 21.67%', meaning: 'Average the three relative misses: 25%, 20% and 20%. B and C have the same percentage miss, although C misses by more minutes.' }]}/><p className="rd-note">All three metrics are 0 for perfect predictions. Lower means smaller errors on the same evaluation records; there is no universal good value.</p></Panel>
}
function SpreadExample() { return <Panel title="Are long deliveries harder to predict?"><p>Illustrative residual ranges, in minutes. A residual is <strong>actual time − our model’s prediction</strong>; zero means an exact prediction.</p><div className="rd-spread-grid">{[{ title: 'Similar spread', widths: [2, 2] }, { title: 'Widening spread', widths: [2, 6] }].map(pattern => <figure key={pattern.title}><figcaption>{pattern.title}</figcaption><svg viewBox="0 0 330 220" role="img" aria-label={`${pattern.title}: short deliveries span minus 2 to plus 2 minutes; long deliveries span minus ${pattern.widths[1]} to plus ${pattern.widths[1]} minutes.`}><line x1="55" y1="25" x2="55" y2="175" stroke="#9ab9b1"/>{[-6, 0, 6].map(tick => <g key={tick}><line x1="55" x2="305" y1={100 - tick * 11} y2={100 - tick * 11} stroke={tick === 0 ? '#557e75' : '#e0eae6'} strokeDasharray="4 4"/><text x="44" y={105 - tick * 11} textAnchor="end">{tick > 0 ? '+' : ''}{tick}</text></g>)}{pattern.widths.map((width, i) => <g key={i}><line x1={125 + i * 125} x2={125 + i * 125} y1={100 - width * 11} y2={100 + width * 11} stroke="#187d76" strokeWidth="14" strokeLinecap="round"/><text x={125 + i * 125} y="198" textAnchor="middle">{i === 0 ? 'Short trips' : 'Long trips'}</text></g>)}</svg></figure>)}</div><p><strong>Left:</strong> both groups miss by roughly the same range. <strong>Right:</strong> long trips have a wider range of misses, so one average error hides a less reliable group.</p><p className="rd-note">These bars illustrate spread, not a fitted dataset or a formal test.</p></Panel> }
function NullExample() { return <Panel title="Example: does distance help predict delivery time?"><div className="rd-null-scene"><img src={nullDelivery} alt="A bicycle courier follows a route to a house while someone examines a clipboard." width="900" height="600"/><div><div className="rd-example-flow"><div><span>Start with H₀</span><strong>Distance has no relationship with delivery time.</strong></div><b aria-hidden="true">→</b><div><span>Look at the data</span><strong>Is there enough evidence to reject that claim?</strong></div></div><p>If the test gives enough evidence, <strong>reject H₀</strong>: the data supports a relationship. Otherwise, <strong>do not reject H₀</strong>: we have not shown a relationship.</p><p className="rd-note">Here we are testing a linear relationship. The next lessons show how to read the test results.</p></div></div></Panel> }
function FExample() { return <Panel title="Does distance help explain delivery time?"><p>H₀ says: <strong>distance has no linear relationship with delivery time.</strong> Imagine two studies of delivery trips. Each tests that same claim, using a cutoff of <strong>0.05</strong>.</p><div className="rd-p-comparisons">{[{ p: 0.01, result: '0.01 is below 0.05 → reject H₀', meaning: 'The data gives evidence that distance is related to delivery time. A promising sign: keep investigating the model and check its prediction errors next.' }, { p: 0.2, result: '0.20 is above 0.05 → do not reject H₀', meaning: 'We have not shown that distance is related to delivery time. Review the inputs or data before relying on this model.' }].map(example => <div key={example.p}><strong>F-test p = {example.p.toFixed(2)}</strong><div className="rd-p-scale" role="img" aria-label={`p-value ${example.p}, ${example.p < .05 ? 'below' : 'above'} the 0.05 threshold on a scale from 0 to 0.25.`}><span className="rd-p-threshold"/><span className="rd-p-point" style={{ left: `${example.p / .25 * 100}%` }}/></div><div className="rd-p-labels"><span>0</span><span>Cutoff: 0.05</span><span>0.25</span></div><h3><Term definition={example.p < .05 ? "The data points to a relationship. A promising sign—keep checking the model." : "No clear relationship found yet. Review the inputs or data; this does not prove H₀ is true."}>{example.result}</Term></h3><p>{example.meaning}</p></div>)}</div><p className="rd-note">These are example test results. A p-value of 0.01 does not mean 1% prediction error. Use MAE to find the average miss in minutes.</p></Panel> }
function CoefficientExample() { return <Panel title="Large compared with how much uncertainty?"><Formula label="Accommodates t equals 5.7166 divided by 0.2238, approximately 25.54" caption={<>The estimate is about 25.5 standard errors from zero.</>}><span>t =</span><Fraction top="5.7166" bottom="0.2238"/><span>≈ 25.54</span></Formula><p>The same Airbnb output gives two very different coefficient rows. The estimate is a change in predicted price with the other inputs held fixed.</p><ExampleTable caption="Two actual coefficient rows, traced to t and p" headers={['Input', 'Estimate', 'Standard error', 't = estimate / SE', 'p-value']} rows={[
 ['Accommodates', '+5.7166', '0.2238', '25.540', '< 2 × 10⁻¹⁶'],
 ['Host profile photo', '−4.1485', '4.1430', '−1.001', '0.317'],
]}/><div className="rd-example-flow"><div><span>Accommodates</span><strong>Estimate ≈ 25.5 standard errors from 0</strong><p>A clear relationship in this model: one extra guest is linked to about $5.72 higher predicted price, with other inputs fixed.</p></div><b aria-hidden="true">↔</b><div><span>Profile photo</span><strong>Estimate ≈ 1 standard error from 0</strong><p>No clear relationship found at the 0.05 cutoff. We cannot confidently say that having a photo is linked to a price difference.</p></div></div><p><strong>What does a zero coefficient mean?</strong> The input adds no change to the prediction when other inputs stay fixed. The test asks whether the apparent effect could just be sample noise.</p><p><strong>A useful sign:</strong> a small p-value and an effect large enough to matter. Accommodates looks promising—then check whether it helps predictions on new data.</p><p><strong>What to avoid:</strong> treating every fitted number as a reliable effect. The photo estimate is about −$4.15, but its uncertainty is too large to draw a clear conclusion. This does not prove that photos never matter.</p><p className="rd-note">A negative t means a negative estimate. Judge evidence using the p-value, which also depends on the test’s degrees of freedom; there is no universal t cutoff here.</p></Panel> }
function OverlapExample() { return <Panel title="Two columns, the same distance"><p>A deliberately exact example: suppose delivery distance is recorded in both kilometres and metres.</p><ExampleTable caption="Illustrative input data" headers={['Delivery', 'Distance in km', 'Distance in metres']} rows={[
 ['A', '1', '1,000'], ['B', '2', '2,000'], ['C', '3', '3,000'],
]}/><div className="rd-example-flow"><div><span>Rule A</span><strong className="rd-inline-equation">Time = 8 + 2 × km</strong></div><b aria-hidden="true">=</b><div><span>Rule B</span><strong className="rd-inline-equation">Time = 8 + 0.002 × metres</strong></div></div><p>Both rules predict <strong>10, 12 and 14 minutes</strong>. Including both distance columns adds no new information: the model cannot uniquely divide the distance effect between their coefficients.</p><p className="rd-note">These are equivalent demonstration rules, not trained models. The Airbnb indicators below overlap strongly rather than being exact copies.</p></Panel> }
function VIFExample() { return <Panel title="Why do these two Airbnb inputs overlap?"><p><strong>Entire.place</strong> tells us whether the listing is an entire place. <strong>Private.room</strong> tells us whether it is a private room.</p><p>In this dataset, almost every listing is one or the other. Knowing one therefore tells us a lot about the other.</p><div className="rd-example-flow"><div><span>Our main question</span><strong>Predict the listing’s price</strong></div><b aria-hidden="true">→</b><div><span>The VIF check</span><strong>Can the other inputs predict Entire.place?</strong></div></div><p>If they can, <strong>Entire.place repeats information already in the model</strong>. Its high VIF flags that overlap.</p><div className="rd-vif-comparison"><h3>Remove one overlapping input, then check again</h3>{[{ label: 'With Private.room included', vif: 12.304416 }, { label: 'After removing Private.room and refitting', vif: 1.473047 }].map(row => <div key={row.label}><span>{row.label}</span><div className="rd-vif-track"><span style={{ width: `${row.vif / 15 * 100}%` }}/></div><strong>{row.vif.toFixed(2)}</strong></div>)}<p className="rd-note">Entire.place VIF, on the same 0–15 scale.</p></div><p><strong>Conclusion:</strong> VIF falls from <strong>12.30 to 1.47</strong>. There is much less overlap after removing Private.room. Next, check that the model still predicts prices well.</p></Panel> }
function RecapExample() { return <Panel title="Walk through the model output"><ol className="rd-recap-walkthrough"><li><strong>What are we predicting?</strong><p>The formula says: predict Airbnb price using guest capacity, bedrooms, room type and the host’s profile picture. <code>data = d.2</code> names the dataset.</p></li><li><strong>How far off are the predictions?</strong><p>The residuals show actual price minus predicted price. The middle error is about −$8.09. The largest miss in these records is about $194.39.</p></li><li><strong>How does each input change the prediction?</strong><p>The intercept starts at $47.95 when all inputs are zero. Each extra guest adds about $5.72; each extra bedroom adds about $5.09, keeping other inputs fixed.</p></li><li><strong>How much price variation does the model explain?</strong><p>R² = 0.4164 means <strong>41.64%</strong>. Adjusted R² is very similar: 0.4163.</p></li><li><strong>Does the model find a relationship?</strong><p>The whole-model p-value is extremely small—below 0.05. This is a promising sign: there is evidence of a relationship beyond random noise.</p></li><li><strong>Which inputs look useful?</strong><p>Use each row’s estimate and standard error to get its t-value, then read its p-value. Guest capacity has a very small p-value. Profile photo has p = 0.317, so we have not shown a clear relationship with price.</p></li></ol><p className="rd-note">The F-test is the first statistical check when evaluating a model. This walkthrough follows the output’s layout.</p></Panel> }
function RSquaredReference() {
  const examples = [
    { value: 0, label: 'No improvement over the mean', description: 'The predictions have the same total squared error as giving every delivery the average time.' },
    { value: 0.5, label: 'Half the variation explained', description: 'The predictions leave half of the mean-only model’s squared error. The worked example above is close: R² = 0.502.' },
    { value: 0.9, label: 'Most variation explained', description: 'The predictions leave only 10% of the mean-only model’s squared error.' },
    { value: 1, label: 'Perfect fit on these records', description: 'Every predicted delivery time matches its actual time: no squared error remains.' },
  ]
  return <Panel title="What does a low or high R² look like?">
    <p>Suppose three deliveries took <strong>10, 20 and 30 minutes</strong>. Their average is <strong>20 minutes</strong>.</p>
    <p>The simplest prediction is therefore <strong>20 minutes for every trip</strong>, ignoring distance. Our illustrative regression uses distance to predict <strong>12, 19 and 29 minutes</strong> instead.</p>
    <div className="rd-delivery-table"><table><caption>Same deliveries, two ways to predict</caption><thead><tr><th scope="col">Delivery</th><th scope="col">Actual time</th><th scope="col">Always use the average</th><th scope="col">Our model’s prediction</th></tr></thead><tbody>{[{ trip: 'A', actual: 10, prediction: 12 }, { trip: 'B', actual: 20, prediction: 19 }, { trip: 'C', actual: 30, prediction: 29 }].map(row => <tr key={row.trip}><th scope="row">{row.trip}</th><td>{row.actual} min</td><td>20 min</td><td>{row.prediction} min</td></tr>)}</tbody></table></div>
    <Reference items={[{ value: 'Average-only error: 200', meaning: '(10 − 20)² + (20 − 20)² + (30 − 20)² = 100 + 0 + 100 minutes².' }, { value: 'Regression error: 6', meaning: '(10 − 12)² + (20 − 19)² + (30 − 29)² = 4 + 1 + 1 minutes².' }]}/>
    <p><strong>R² = 1 − 6 / 200 = 0.97.</strong> Using distance reduces squared error by <strong>97%</strong> compared with always predicting 20 minutes, on these three deliveries.</p>
    <h3>A question that does not use the average-only baseline</h3>
    <p><strong>How many minutes do the predictions miss by?</strong> The absolute misses are 2, 1 and 1 minutes. <strong>MAE = (2 + 1 + 1) / 3 ≈ 1.33 minutes.</strong></p>
    <p>R² tells us the improvement over the average-only prediction. MAE tells us the size of the misses directly. If you need a different baseline, such as a delivery schedule, compare prediction errors against that schedule separately.</p>
    <h3>Reference points for R²</h3>
    <div className="rd-r2-legend"><span><i className="rd-explained-key"/>Variation explained</span><span><i className="rd-remaining-key"/>Squared error remaining</span></div>
    <div className="rd-r2-references">{examples.map(example => <div className="rd-r2-reference" key={example.value}>
      <div className="rd-r2-value"><strong>R² = {example.value.toFixed(1)}</strong><span>{example.label}</span></div>
      <div className="rd-r2-bar" role="img" aria-label={`${example.value * 100}% of variation explained; ${(1 - example.value) * 100}% of the mean-only squared error remains.`}>
        {example.value > 0 && <span className="rd-r2-explained" style={{ width: `${example.value * 100}%` }}>{example.value * 100}%</span>}
        {example.value < 1 && <span className="rd-r2-remaining" style={{ width: `${(1 - example.value) * 100}%` }}>{Math.round((1 - example.value) * 100)}%</span>}
      </div><p>{example.description}</p>
    </div>)}</div>
    <p className="rd-note">Illustrative reference points, not fitted delivery data or universal quality thresholds. A high R² describes fit on the evaluated records; it does not guarantee accurate future deliveries. R² can also be negative when predictions are worse than the mean-only baseline.</p>
  </Panel>
}

export function RDRSquared() { return <Lesson number="14.3" title="R-squared" lead={<>R-squared measures how well your model <u>explains the <strong>variance</strong></u> in the dependent variable you are predicting.</>}><Panel title="What does R² explain?"><p>It explains <strong>variation in the actual values of the dependent variable</strong>: how much those values differ from their average. For delivery time, actual trips take different amounts of time. R² measures how much of those differences the model captures.</p><p>Read the <strong>0–1 scale</strong> like this:</p><div className="rd-r2-endpoints"><div><strong>R² = 1</strong><span><b>All the variation is explained.</b> Every prediction matches its actual value; no squared error remains.</span></div><div><strong>R² = 0</strong><span><b>None of the variation is explained.</b> The predictions have the same total squared error as always predicting the average.</span></div></div><p><strong>Between 0 and 1:</strong> R² = 0.7 means the model accounts for 70% of the variation around the average, leaving 30% unexplained. It does not mean 70% of predictions are correct.</p><p className="rd-note">“Explained” means accounted for statistically, not proven to be caused by the inputs. R² can be negative if predictions are worse than the average-only baseline.</p></Panel><Panel title="R² = 1 − SSE / TSS"><Formula label="R-squared equals one minus SSE divided by TSS" caption={<>Compare the model’s squared error with the total variation around the mean.</>}><span>R² = 1 −</span><Fraction top="SSE" bottom="TSS"/></Formula><p><strong>SSE:</strong> sum of squared distances from actual values to predictions.<br/><strong>TSS:</strong> sum of squared distances from actual values to their mean.</p><p><strong>Adjusted R-squared</strong> “penalizes” the R-squared value based on the number of variables included in the model.</p><p className="rd-note">Adding an input can raise ordinary R² even if it adds little value. Adjusted R² can fall when the improvement is too small to justify the extra input.</p></Panel><Visual src={page230} alt="Line y = 12 + 0.4x beside all ten observations, predictions, squared errors and mean deviations. SSE = 722, TSS = 1450, R-squared = 0.502."/><p className="rd-mean-note">ȳ = (10 + 25 + 20 + 30 + 40 + 15 + 40 + 30 + 50 + 40) / 10 = 300 / 10 = 30: the mean of the ten actual y-values.</p><p className="rd-note">The model explains about 50.2% of the variation in these records. This does not establish accuracy on new data.</p><Explanation><RSquaredReference/><Use why="Measure how well the model explains variance in the dependent variable." when="When comparing how much variance models explain. Use adjusted R² to account for the number of inputs."/></Explanation></Lesson> }

export function RDErrorMetrics() { return <Lesson number="14.4" title="Mean error metrics" lead={<>Mean error metrics measure how well your regression model <strong><u>predicts</u></strong>, as opposed to how well it <u>explains <strong>variance</strong></u>, like R-squared.</>}><Panel title="Three ways to summarize error"><p className="rd-metric-purpose">Use these metrics to <strong>compare predictive accuracy across different regression models</strong>, using the same evaluation records.</p><div className="rd-metric-definitions rd-metric-formulas"><div><h3>MSE</h3><div className="rd-formula" role="math" aria-label="MSE equals the sum of squared actual minus predicted values, divided by n"><span className="rd-fraction"><span>∑<sub>i</sub> (y<sub>i</sub> − prediction<sub>i</sub>)<sup>2</sup></span><span>n</span></span></div><p className="rd-formula-caption">Average of the <strong>squared</strong> distance between actual and predicted values.</p><p>Average squared error. Gives large misses more weight.</p></div><div><h3>MAE</h3><div className="rd-formula" role="math" aria-label="MAE equals the sum of absolute actual minus predicted values, divided by n"><span className="rd-fraction"><span>∑<sub>i</sub> |y<sub>i</sub> − prediction<sub>i</sub>|</span><span>n</span></span></div><p className="rd-formula-caption">Average of the <strong>absolute</strong> distance between actual and predicted values.</p><p>Average absolute error. Keeps the outcome’s original units.</p></div><div><h3>MAPE</h3><div className="rd-formula" role="math" aria-label="MAPE equals the average absolute error divided by each absolute actual value, multiplied by 100 percent"><span className="rd-fraction"><span>∑<sub>i</sub> <span className="rd-fraction rd-inner-fraction"><span>|y<sub>i</sub> − prediction<sub>i</sub>|</span><span>|y<sub>i</sub>|</span></span></span><span>n</span></span><span className="rd-percent">× 100%</span></div><p className="rd-formula-caption">Average of the absolute error relative to each actual value, expressed as a <strong>percentage</strong>.</p><p>Average percentage error. Makes the relative size of misses easier to read.</p></div></div><p className="rd-formula-key">y<sub>i</sub> = actual value · prediction<sub>i</sub> = our model’s prediction · n = number of records · ∑ = add across all records</p></Panel><Panel title="MSE: 722 / 10 = 72.2"><Visual src={page232} alt="MSE scatterplot, ten-row calculation table, squared-error total 722 and division by ten giving 72.2."/></Panel><Panel title="MAE: 74 / 10 = 7.4"><Visual src={page233} alt="MAE scatterplot and full table of absolute errors totaling 74, giving MAE 7.4."/></Panel><Panel title="MAPE: 3.233… / 10 × 100% = 32.33%"><Visual src={page234} alt="MAPE scatterplot and complete table including absolute and proportional errors, giving 32.33 percent."/></Panel><p className="rd-note">The source tables use prediction − actual for signed error; squaring or taking its absolute value gives the same metrics. MAPE is undefined when an actual value is zero.</p><Explanation><ErrorExample/><Panel title="MSE: emphasize large misses"><Use why="Give large errors more weight when comparing models." when="Particularly useful when outliers or extreme values are important to predict."/></Panel><Panel title="MAE: read the miss in original units"><Use why="Measure the average miss in the original units." when="Useful when you want to reduce the impact of outliers on model selection, compared with MSE."/></Panel><Panel title="MAPE: read the relative miss"><Use why="Compare model errors on a more intuitive percentage scale." when="Useful when the dependent variable is on a large scale or percentages are easier to interpret. Avoid actual values at or near zero."/></Panel><p className="rd-note">Consider all three metrics: each gives helpful context about model performance. Compare models using the same evaluation records.</p></Explanation></Lesson> }

export function RDHomoskedasticity() { return <Lesson number="14.5" title="Homoskedasticity" lead={<>Homoskedasticity means a consistent spread of <Term definition={residualDefinition}>residuals</Term> across the input range.</>}><Visual src={page236} alt="Plots side by side: constant-width scatter around a fitted line versus scatter widening at higher input values, with turquoise bounds and yellow fitted lines."/><Panel title="Compare the spread"><p><strong>Left:</strong> <Term definition={residualDefinition}>residuals</Term> have a similar spread across the range.<br/><strong>Right:</strong> residuals grow at higher input values: <Term definition="Heteroskedasticity means the prediction errors have a changing spread—for example, larger misses on long trips than short trips.">heteroskedasticity</Term>.</p><p>A visual check can reveal the pattern; a Breusch–Pagan test can supplement it.</p></Panel><p className="rd-note">Constant variance and normally distributed residuals are separate assumptions. Changing variance alone does not prove that predictions fail to generalize.</p><Explanation><SpreadExample/><Use why="Check for consistent scatter in the residuals across the input range." when="When checking whether the model’s errors become larger for certain input values. Start with a visual check."/></Explanation></Lesson> }



export function RDNullHypothesis() { return <Lesson number="14.6" title="Null hypothesis" lead={<>The <strong>null hypothesis (H₀)</strong> is the starting claim that there is <u><strong>no relationship</strong></u>; the pattern we see could be due to chance.</>}><Panel title="The idea behind the test"><p className="rd-prominent">Does our model find a relationship, or could the result just be random?</p><p>We look for evidence to <strong>reject the null hypothesis</strong>—evidence that the model’s inputs are related to the value we want to predict.</p><p className="rd-note">The course calls H₀ “the hypothesis that your model is garbage.” Here, that means no linear relationship—not that the test measures prediction accuracy.</p></Panel><Explanation><NullExample/><Use why="Check whether an apparent relationship could be explained by chance." when="Before interpreting a statistical test: first state the claim you are testing."/><p className="rd-note">Rejecting H₀ does not guarantee accurate predictions. Check prediction errors separately.</p></Explanation></Lesson> }


export function RDFSignificance() { return <Lesson number="14.7" title="F-statistic & F-significance" lead={<>F-significance: <strong>“the probability that the null hypothesis cannot be rejected.”</strong><br/><small>More precisely: if H₀ were true, how likely would a test result this strong be?</small></>}><Panel title="What does F-significance mean?"><p className="rd-prominent">Do the inputs help explain the result, or could the pattern just be random?</p><p>Start with H₀: <strong>the inputs have no linear relationship with what we want to predict.</strong></p><p>F-significance is the <Term definition="A p-value asks: if H₀ were true, how likely would a test result this strong or stronger be? A smaller value gives stronger evidence against H₀.">p-value</Term> for this test. <strong>The smaller it is, the stronger the evidence to reject H₀.</strong></p></Panel><Panel title="The usual cutoff: 0.05"><p>Common practice is to choose <strong><u>0.05 (5%)</u></strong> as the cutoff before testing.</p><ul><li><strong>Below 0.05:</strong> reject H₀. The model is statistically significant: <strong>there is evidence of a relationship beyond random noise or chance.</strong></li><li><strong>0.05 or above:</strong> do not reject H₀. We have not shown that the inputs help.</li></ul><p className="rd-note">The related confidence level is 95%: 100% − 5%. This does not mean the model is 95% accurate.</p><p>Then check prediction errors on new data to see how well the model predicts.</p></Panel><aside className="rd-use" aria-label="Pro tip"><h2>Pro tip</h2><p><strong>Check F-significance first</strong> when evaluating the model’s statistical significance.</p><p><strong>Above your cutoff?</strong> Review the inputs and training data; you may need to revise and retrain the model.</p><p><strong>Below your cutoff?</strong> Move on to <Term definition="Check each input separately to see which ones have evidence of a relationship with the value you are predicting. The next lesson explains this.">coefficient-level significance</Term>.</p></aside><Visual src={page243} alt="Annotated Airbnb regression output. The bottom highlighted line contains the whole-model F-statistic and its p-value; the coefficient tests appear above it."/><Panel title="Read the bottom line of the model output"><pre className="rd-console">F-statistic: 3543 on 6 and 29790 DF, p-value: &lt; 2.2e-16</pre><ExampleTable caption="Read each part of that line" headers={['Output', 'Plain meaning', 'Where it comes from']} rows={[
['F-statistic: 3543', 'The overall test score. Larger values give stronger evidence against H₀.', 'Variation explained per input ÷ unexplained variation per remaining degree of freedom.'],
['6', 'Six input coefficients are tested together.', 'Count the model’s inputs; do not count the intercept.'],
['29790 DF', '29,790 degrees of freedom remain for estimating error.', '29,797 records − 6 input coefficients − 1 intercept = 29,790.'],
['p-value: < 2.2e-16', 'An extremely small probability: less than 0.00000000000000022.', 'Compare F = 3543 with an F-distribution using the two DF numbers: 6 and 29,790.'],
]}/><p><Term definition="Degrees of freedom (DF) count how much independent information remains after estimating model parameters. Here, each fitted coefficient uses one degree of freedom.">Degrees of freedom (DF)</Term> are the information left after fitting the model. This model estimates seven numbers: six input coefficients and one intercept.</p><Formula label="F is approximately 0.4164 divided by 6, over 1 minus 0.4164 divided by 29790, approximately 3543" caption={<>Using the reported R² = 0.4164. The displayed values are rounded.</>}><span>F ≈</span><Fraction top="0.4164 / 6" bottom="(1 − 0.4164) / 29,790"/><span>≈ 3543</span></Formula><p><strong>What is the p-value?</strong> Suppose the inputs really had no linear relationship with price. How likely would we be to get an F-score this large or larger? That probability is the p-value.</p><p><strong>What do we conclude?</strong> This p-value is far below <strong>0.05</strong>, so we reject H₀. There is evidence that at least one input is related to price. Next, check the individual coefficients.</p></Panel><p className="rd-note">A small p-value gives evidence of a relationship. It does not tell us how small the prediction errors are.</p><Explanation><FExample/><Use why="Check whether the model’s inputs, taken together, help explain the result." when="Start here when reading the model’s statistical tests. If p is below 0.05, check which individual inputs help next."/></Explanation></Lesson> }

export function RDTValues() { return <Lesson number="14.8" title="T-statistics & p-values" lead={<>Read each input’s <CoefficientTerm name="Coefficient">coefficient</CoefficientTerm>, <CoefficientTerm name="Estimate">estimate</CoefficientTerm>, <CoefficientTerm name="Standard error">standard error</CoefficientTerm>, <CoefficientTerm name="t-value">t-statistic</CoefficientTerm> and <CoefficientTerm name="p-value"/> together.</>}><aside className="rd-use" aria-label="Quick definitions"><h2>A quick reminder</h2><p><strong><CoefficientTerm name="t-value"/> (t-statistic):</strong> how far the estimate is from zero, compared with its uncertainty.</p><p><strong><CoefficientTerm name="p-value"/>:</strong> helps us decide whether there is evidence that this input is related to price. Below 0.05 is the usual cutoff.</p><p><strong>Input (independent variable):</strong> what the model uses—for example, guest count (“accommodates”).</p><p><strong>Coefficient:</strong> the number multiplying that input. Here it is <strong>5.7166</strong>: one extra guest adds about <strong>$5.72</strong> to predicted price, keeping the other inputs fixed.</p><p className="rd-note">So “individual model coefficients” means the estimated number for each input. The intercept is another coefficient: the model’s starting value.</p><p className="rd-note">Hover over or click an underlined term for a short definition.</p></aside><Visual src={page239} alt="Regression output with t-value and p-value columns highlighted. Accommodates estimate 5.7166, standard error 0.2238, t 25.540; host profile photo p = 0.317."/><Panel title="t-statistic"><Formula label="t equals coefficient estimate divided by standard error" caption={<>The coefficient estimate measured in units of its standard error.</>}><span>t =</span><Fraction top={<><CoefficientTerm name="Coefficient">coefficient</CoefficientTerm> <CoefficientTerm name="Estimate">estimate</CoefficientTerm></>} bottom={<CoefficientTerm name="Standard error">standard error</CoefficientTerm>}/></Formula><p><strong>Accommodates:</strong> 5.7166 / 0.2238 ≈ 25.54, with p &lt; 2 × 10⁻¹⁶.</p><p><strong>Host profile photo:</strong> −4.1485 / 4.1430 ≈ −1.001, with p = 0.317. Above 0.05: we have not shown a clear relationship between having a profile photo and price.</p></Panel><p className="rd-note">A small p-value suggests a relationship. It does not tell us how large or useful that relationship is.</p><Explanation><CoefficientExample/><Use why="Check statistical significance for individual model coefficients." when="After the whole-model test. Use the t-statistic and p-value to assess evidence that each coefficient differs from zero."/></Explanation></Lesson> }

export function RDMulticollinearity() { return <Lesson number="14.9" title="Multicollinearity" lead="Multicollinearity occurs when predictors carry strongly overlapping information."><Panel title="One input can help predict another"><p className="rd-prominent">Height ↔ weight</p><p>As in the course example, correlated inputs can allow several combinations of coefficients to make similar predictions. Individual coefficients become harder to interpret reliably.</p></Panel><Panel title="How do we measure it?"><p><strong>Variance inflation factor (VIF)</strong> quantifies how well each input can be predicted from the others. Use it to investigate redundant inputs.</p></Panel><Explanation><OverlapExample/><Visual src={roomCounts} alt="Room-type counts: neither type 816; private room only 15,815; entire place only 13,166; both types 0. The indicators largely encode opposite categories."/><p className="rd-note">The Airbnb example makes the overlap visible: almost every listing is either an entire place or a private room, and none is both.</p><Panel title="What is the end goal?"><p><strong>Keep useful information without repeating it unnecessarily.</strong> When two inputs tell us almost the same thing, it becomes harder to tell how much each one contributes.</p><p><strong>Exact duplicates?</strong> Keep one representation—for example, distance in kilometres or metres.</p><p><strong>Strong overlap?</strong> Use VIF to investigate. Consider removing one input if it adds little useful information; a high VIF is a warning, not an automatic delete instruction.</p><p><strong>Then refit and check again:</strong> did VIF improve, and do predictions still work well on new data? The goal is clearer, more stable coefficients while keeping useful predictions.</p></Panel><Use why="Identify highly correlated inputs that can make coefficient estimates unreliable." when="When one input can predict another, such as height and weight. Use VIF to measure the overlap."/></Explanation></Lesson> }

export function RDVIF() { return <Lesson number="14.10" title="Variance inflation factor" lead="Predict each input from the remaining inputs, then use that auxiliary model’s R² to calculate VIF."><Visual src={page241} alt="Calculation flow from the original regression to auxiliary regressions predicting x1 and x2, then 1 divided by 1 minus R-squared, yielding VIF for each input."/><aside className="rd-use" aria-label="Formula reminder"><h2>A quick reminder: α and ε</h2><p><strong><Term definition="The intercept is the model’s starting value: its predicted value when all inputs are zero.">α (alpha) = intercept</Term>:</strong> the starting value, before adding the input contributions.</p><p><strong><Term definition="Epsilon is the error term: the part of the actual value that the model does not explain. A fitted residual estimates this error.">ε (epsilon) = error term</Term>:</strong> the part the model does not explain. It looks like an E.</p><p>For Airbnb, <strong>α</strong> is the starting price before adding the input contributions. The observed error is the listing’s <strong>actual price − predicted price</strong>.</p></aside><Panel title="Airbnb price example"><p>We are trying to <strong>predict the price of an Airbnb listing</strong>. Price is the dependent variable; the listing details used to predict it are the <strong>independent variables (inputs)</strong>.</p><p>We calculate <strong>VIF for each input</strong> to see how much it overlaps with the other inputs. A high VIF flags information that may be repeated.</p><Visual src={page242} alt="Actual VIF results: Entire.place 12.304416 and Private.room 11.791492. Removing Private.room and refitting reduces Entire.place VIF to 1.473047. Full before and after output and room-type frequency table are preserved."/></Panel><p className="rd-note">VIF above 10 is the course’s rule of thumb for investigating overlap. Here, remove Private.room, refit, and recalculate. The frequency table confirms that the two room indicators largely encode opposite categories.</p><Explanation><VIFExample/><Use why="Measure multicollinearity and identify potentially redundant inputs." when="Investigate VIF values above 10 as a rule of thumb. Choose an overlapping input to remove, re-run the model, and recalculate VIF."/></Explanation></Lesson> }

export function RDRecap() { return <Lesson number="14.11" title="Recap: sample model output" lead="Locate each diagnostic in the same Airbnb regression output."><p><strong>Price is Y (the dependent variable)</strong>—what we want to predict. <strong>The listing details are the Xs (independent variables)</strong>—guest capacity, bedrooms, room type and whether the host has a profile picture.</p><RecapGraphic/><Panel title="Read the residuals from smallest to largest"><p><strong>Residual = actual price − predicted price.</strong> Negative means the prediction was too high; positive means it was too low.</p><ExampleTable caption="Five points summarizing the fitted price errors" headers={['Label', 'Error', 'What it means']} rows={[
['Min', '−$135.057', 'Smallest signed error: the prediction was $135.057 too high.'],
['1Q — first quartile', '−$27.091', 'The 25% point: roughly a quarter of errors are at or below this value.'],
['Median', '−$8.091', 'The middle error: half are below it and half above.'],
['3Q — third quartile', '+$20.909', 'The 75% point: roughly three quarters of errors are at or below this value.'],
['Max', '+$194.388', 'Largest signed error: the prediction was $194.388 too low.'],
]}/><p><strong>Worst miss shown: about $194.39.</strong> This is the largest absolute error in these fitted records. New listings could have larger errors.</p></Panel><Explanation><RecapExample/><Panel title="What else should we check?"><p>This output does not show everything. Check whether errors have a consistent spread, whether inputs overlap (VIF), and how well prices are predicted on new data.</p></Panel></Explanation></Lesson> }
